CREATE OR REPLACE FUNCTION private.accept_household_invitation_impl(p_invitation_id uuid, p_token text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_invite public.household_invitations%rowtype;
  v_token_hash bytea;
  v_user_email text;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in is required';
  end if;

  select *
    into v_invite
  from public.household_invitations
  where id=p_invitation_id
  for update;

  if not found then
    raise exception 'Invitation not found';
  end if;

  if v_invite.status <> 'pending' then
    raise exception 'Invitation is no longer active';
  end if;

  if v_invite.expires_at <= now() then
    update public.household_invitations
    set status='expired'
    where id=p_invitation_id;
    raise exception 'Invitation has expired';
  end if;

  select token_hash
    into v_token_hash
  from private.household_invitation_tokens
  where invitation_id=p_invitation_id;

  if v_token_hash is null
     or extensions.digest(coalesce(p_token,''),'sha256') <> v_token_hash then
    raise exception 'Invitation token is invalid';
  end if;

  select lower(email)
    into v_user_email
  from auth.users
  where id=(select auth.uid());

  if v_user_email is null or v_user_email <> lower(v_invite.email) then
    raise exception 'Sign in using the email address that received this invitation';
  end if;

  insert into public.household_members(household_id,user_id,role,status)
  values(v_invite.household_id,(select auth.uid()),v_invite.role,'active')
  on conflict(household_id,user_id) do update
  set role=excluded.role,
      status='active';

  update public.household_invitations
  set status='accepted',
      accepted_by=(select auth.uid()),
      accepted_at=now()
  where id=p_invitation_id;

  delete from private.household_invitation_tokens
  where invitation_id=p_invitation_id;

  return v_invite.household_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.admin_get_digital_book_impl(p_book_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if (select auth.uid()) is null or not private.is_content_admin() then
    raise exception 'Content administrator required' using errcode='42501';
  end if;
  return (select manifest from private.digital_book_manifests where book_id=p_book_id);
end;
$function$

CREATE OR REPLACE FUNCTION private.admin_get_production_launch_gate_impl()
 RETURNS TABLE(area text, check_key text, title text, severity text, passed boolean, detail text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_active_products bigint;
  v_queued_notifications bigint;
  v_active_households bigint;
begin
  if not private.is_app_admin() then
    raise exception 'Adventure Club administrator access required';
  end if;

  select count(*) into v_active_products from public.products where status='active';
  select count(*) into v_queued_notifications
    from public.notification_deliveries
    where status='queued' and next_attempt_at<=now();
  select count(*) into v_active_households
    from public.households where status='active';

  return query select 'DC Governance','locked_standards','Locked DC standards active','blocker',
    (select count(*)>=5 from public.dc_governance_standards s where s.is_active=true and s.is_locked=true),
    (select count(*)::text||' locked active standard(s)' from public.dc_governance_standards s where s.is_active=true and s.is_locked=true);

  return query select 'DC Governance','public_content_current_approval','Published creative content has current approval','blocker',
    not exists(
      select 1 from public.dc_governance_review_status s
      where (
        (s.entity_type='book' and s.entity_status in ('coming_soon','published'))
        or (s.entity_type in ('adventure','challenge','content_item','devotional_series','family_faith_guide') and s.entity_status in ('scheduled','published'))
        or (s.entity_type in ('scripture_passage','power_verse','prayer_prompt','identity_truth','event') and s.entity_status='published')
        or (s.entity_type='product' and s.entity_status='active')
      ) and coalesce(s.approval_current,false)=false
    ),
    (select count(*)::text||' public item(s) with stale or missing DC approval'
      from public.dc_governance_review_status s
      where (
        (s.entity_type='book' and s.entity_status in ('coming_soon','published'))
        or (s.entity_type in ('adventure','challenge','content_item','devotional_series','family_faith_guide') and s.entity_status in ('scheduled','published'))
        or (s.entity_type in ('scripture_passage','power_verse','prayer_prompt','identity_truth','event') and s.entity_status='published')
        or (s.entity_type='product' and s.entity_status='active')
      ) and coalesce(s.approval_current,false)=false);

  return query select 'Theology','dear_god_prayers','All structured prayers begin Dear God','blocker',
    not exists(
      select 1 from public.prayer_prompts where prompt_text is not null and btrim(prompt_text) !~* '^Dear[[:space:]]+God[[:space:]]*,'
      union all
      select 1 from public.devotional_days where prayer_prompt is not null and btrim(prayer_prompt)<>'' and btrim(prayer_prompt) !~* '^Dear[[:space:]]+God[[:space:]]*,'
      union all
      select 1 from public.family_faith_guides where prayer_prompt is not null and btrim(prayer_prompt)<>'' and btrim(prayer_prompt) !~* '^Dear[[:space:]]+God[[:space:]]*,'
    ),
    'Prayer database enforcement active';

  return query select 'Privacy','required_consent_policies','Required guardian consent policies are active','blocker',
    exists(select 1 from public.consent_policies cp where cp.is_active=true and cp.required_for_core_service=true),
    (select count(*)::text||' required active consent policy/policies' from public.consent_policies cp where cp.is_active=true and cp.required_for_core_service=true);

  return query select 'Guardian Safety','guardian_pin_coverage','Active family hubs have guardian PIN protection','blocker',
    (v_active_households=0 or not exists(
      select 1 from public.households h where h.status='active'
        and not exists(select 1 from private.household_guardian_security hgs where hgs.household_id=h.id)
    )),
    (select count(*)::text||' active household(s) missing guardian PIN'
      from public.households h where h.status='active'
        and not exists(select 1 from private.household_guardian_security hgs where hgs.household_id=h.id));

  return query select 'Notifications','delivery_cron','Notification delivery worker cron is active','blocker',
    exists(select 1 from cron.job where jobname='dc-notification-delivery-worker' and active=true),
    coalesce((select 'Schedule: '||schedule from cron.job where jobname='dc-notification-delivery-worker' limit 1),'Cron job missing');

  return query select 'Notifications','delivery_worker_recent','Notification worker has a recent successful run','blocker',
    exists(select 1 from public.delivery_worker_runs dwr where dwr.worker_key='notification-delivery-worker' and dwr.status in ('succeeded','partial') and dwr.completed_at>=now()-interval '5 minutes'),
    coalesce((select 'Last run: '||completed_at::text||' · '||status from public.delivery_worker_runs dwr where dwr.worker_key='notification-delivery-worker' order by dwr.started_at desc limit 1),'Worker has never completed');

  return query select 'Notifications','email_provider','Guardian email delivery provider configured','blocker',
    exists(select 1 from public.integration_providers ip where ip.provider_key='email-primary' and ip.status='active' and ip.health_status in ('healthy','degraded')),
    coalesce((select ip.status||' / '||ip.health_status from public.integration_providers ip where ip.provider_key='email-primary' limit 1),'Email provider record missing');

  return query select 'Notifications','push_provider','Guardian push provider configured','warning',
    exists(select 1 from public.integration_providers ip where ip.provider_key='push-primary' and ip.status='active' and ip.health_status in ('healthy','degraded')),
    coalesce((select ip.status||' / '||ip.health_status from public.integration_providers ip where ip.provider_key='push-primary' limit 1),'Push provider record missing');

  return query select 'Notifications','queued_delivery_backlog','No overdue notification delivery backlog','blocker',
    v_queued_notifications=0,
    v_queued_notifications::text||' due queued delivery/deliveries';

  return query select 'Communications','reminder_rules','At least one automated reminder rule configured','warning',
    exists(select 1 from public.notification_reminder_rules nrr where nrr.status='active'),
    (select count(*)::text||' active reminder rule(s)' from public.notification_reminder_rules nrr where nrr.status='active');

  return query select 'Privacy','privacy_cleanup_cron','Privacy export cleanup cron is active','blocker',
    exists(select 1 from cron.job where jobname='dc-privacy-export-cleanup-daily' and active=true),
    coalesce((select 'Schedule: '||schedule from cron.job where jobname='dc-privacy-export-cleanup-daily' limit 1),'Privacy cleanup cron missing');

  return query select 'Commerce','checkout_cleanup_cron','Expired checkout cleanup cron is active','blocker',
    exists(select 1 from cron.job where jobname='dc-checkout-expiry-cleanup' and active=true),
    coalesce((select 'Schedule: '||schedule from cron.job where jobname='dc-checkout-expiry-cleanup' limit 1),'Checkout cleanup cron missing');

  return query select 'Commerce','active_products_governed','All active products have current DC approval','blocker',
    not exists(
      select 1 from public.products p
      left join public.dc_governance_review_status s on s.entity_type='product' and s.entity_id=p.id
      where p.status='active' and coalesce(s.approval_current,false)=false
    ),
    (select count(*)::text||' active product(s) without current approval'
      from public.products p
      left join public.dc_governance_review_status s on s.entity_type='product' and s.entity_id=p.id
      where p.status='active' and coalesce(s.approval_current,false)=false);

  return query select 'Commerce','payment_provider','Hosted payment provider ready when store is active','blocker',
    (v_active_products=0 or exists(
      select 1 from public.integration_providers ip
      where ip.provider_key='commerce-primary' and ip.status='active' and ip.health_status in ('healthy','degraded')
    )),
    case when v_active_products=0 then 'No active products, payment provider not required yet'
      else coalesce((select ip.status||' / '||ip.health_status from public.integration_providers ip where ip.provider_key='commerce-primary' limit 1),'Commerce provider record missing') end;

  return query select 'Commerce','webhook_health','No payment webhook failures in the last 24 hours','blocker',
    not exists(select 1 from public.payment_webhook_events pwe where pwe.status='failed' and pwe.received_at>=now()-interval '24 hours'),
    (select count(*)::text||' failed webhook event(s) in 24h' from public.payment_webhook_events pwe where pwe.status='failed' and pwe.received_at>=now()-interval '24 hours');

  return query select 'Commerce','stale_pending_orders','No stale pending-payment orders','blocker',
    not exists(select 1 from public.orders o where o.status='pending_payment' and o.created_at<now()-interval '1 hour'),
    (select count(*)::text||' stale pending order(s)' from public.orders o where o.status='pending_payment' and o.created_at<now()-interval '1 hour');

  return query select 'Operations','open_privacy_requests','No aging unresolved privacy requests','warning',
    not exists(select 1 from public.data_privacy_requests dpr where dpr.status not in ('completed','canceled','rejected') and dpr.created_at<now()-interval '7 days'),
    (select count(*)::text||' privacy request(s) open longer than 7 days' from public.data_privacy_requests dpr where dpr.status not in ('completed','canceled','rejected') and dpr.created_at<now()-interval '7 days');
end;
$function$

CREATE OR REPLACE FUNCTION private.admin_prepare_digital_book_impl(p_book_id uuid, p_manifest jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous jsonb; reference jsonb;
begin
  if (select auth.uid()) is null or not private.is_content_admin() then
    raise exception 'Content administrator required' using errcode='42501';
  end if;
  perform 1 from public.books where id=p_book_id for update;
  if not found then raise exception 'Book not found'; end if;
  if not private.digital_book_manifest_valid(p_book_id,p_manifest) then raise exception 'Invalid digital book manifest'; end if;
  if exists (select 1 from jsonb_array_elements(p_manifest->'pages') page
    where not exists (select 1 from storage.objects o where o.bucket_id='dc-digital-books' and o.name=page->>'path')) then
    raise exception 'Upload every page before preparing this digital edition';
  end if;
  select manifest into previous from private.digital_book_manifests where book_id=p_book_id;
  reference:=jsonb_build_object('revision',p_manifest->>'revision','sha256',encode(extensions.digest(p_manifest::text,'sha256'),'hex'));
  if previous=p_manifest and exists (select 1 from public.books where id=p_book_id and metadata->'digital_reader'=reference) then
    return p_manifest->>'revision';
  end if;
  if previous->>'revision'=p_manifest->>'revision' then raise exception 'Changed pages require a new edition revision'; end if;
  insert into private.digital_book_manifests(book_id,manifest) values(p_book_id,p_manifest)
    on conflict(book_id) do update set manifest=excluded.manifest,updated_at=now();
  -- Existing book mutation audit and governance triggers record and invalidate this change.
  update public.books set metadata=jsonb_set(metadata,'{digital_reader}',reference),status='draft' where id=p_book_id;
  return p_manifest->>'revision';
end;
$function$

CREATE OR REPLACE FUNCTION private.attribute_referral_impl(p_code text, p_referred_household_id uuid, p_source text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_code_id uuid;
  v_owner_household uuid;
begin
  if not private.can_manage_household(p_referred_household_id) then
    raise exception 'Guardian household access required';
  end if;

  select id,household_id into v_code_id,v_owner_household
  from public.referral_codes
  where code=upper(trim(p_code))
    and is_active=true;

  if v_code_id is null then
    return false;
  end if;

  if v_owner_household=p_referred_household_id then
    return false;
  end if;

  insert into public.referral_attributions(
    referral_code_id,referred_household_id,source
  )
  values(v_code_id,p_referred_household_id,nullif(trim(p_source),''))
  on conflict(referred_household_id) do nothing;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION private.audit_admin_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_entity_id text;
  v_before jsonb;
  v_after jsonb;
begin
  if tg_op = 'INSERT' then
    v_after := to_jsonb(new);
    v_entity_id := v_after ->> 'id';
  elsif tg_op = 'UPDATE' then
    v_before := to_jsonb(old);
    v_after := to_jsonb(new);
    v_entity_id := coalesce(v_after ->> 'id', v_before ->> 'id');
  else
    v_before := to_jsonb(old);
    v_entity_id := v_before ->> 'id';
  end if;

  if v_actor is not null and private.is_app_admin() then
    insert into public.admin_audit_log (
      actor_user_id,
      action,
      entity_type,
      entity_id,
      before_state,
      after_state,
      metadata
    )
    values (
      v_actor,
      lower(tg_op),
      tg_table_name,
      v_entity_id,
      v_before,
      v_after,
      jsonb_build_object('schema', tg_table_schema)
    );
  end if;

  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION private.award_completed_book_adventure(p_child_profile_id uuid, p_book_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ready boolean;
  v_xp integer;
begin
  if (select auth.uid()) is null or not private.can_manage_child(p_child_profile_id) then
    raise exception 'Guardian household access required';
  end if;
  if not private.child_has_book_companion_access(p_child_profile_id,p_book_id) then
    raise exception 'Book companion access required';
  end if;
  -- This wrapper accepts identifiers only, never caller-selected XP or sources.
  -- The invoker RPC must already have persisted completed progress under RLS.
  perform 1 from public.child_book_progress
  where child_profile_id=p_child_profile_id and book_id=p_book_id
    and status='adventure_completed' and adventure_completed_at is not null
  for update;
  if not found then raise exception 'Completed Book Adventure required'; end if;

  select adventure_completion_xp into v_xp from public.books
  where id=p_book_id and (status in ('coming_soon','published') or private.is_app_admin());
  if not found then raise exception 'Book is not available'; end if;

  -- Recheck authoritative required steps inside this privileged boundary.
  -- A hidden/incomplete linked requirement must not become an award shortcut.
  select ready_for_adventure_completion into v_ready
  from public.get_child_book_adventure_summary(p_child_profile_id,p_book_id);
  if not coalesce(v_ready,false) then
    raise exception 'Required Book Adventure steps are not complete';
  end if;

  if coalesce(v_xp,0)>0 then
    perform private.award_xp_event(p_child_profile_id,v_xp,
      'book_adventure_completed','book',p_book_id,'Full Book Adventure completed');
  end if;
  perform private.evaluate_child_badges(p_child_profile_id);
end;
$function$

CREATE OR REPLACE FUNCTION private.award_xp_event(p_child_profile_id uuid, p_points integer, p_event_type text, p_source_type text, p_source_id uuid, p_description text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if coalesce(p_points,0) <= 0 then
    return;
  end if;

  insert into public.xp_ledger (
    child_profile_id, points, event_type, source_type, source_id, description
  )
  values (
    p_child_profile_id, p_points, p_event_type, p_source_type, p_source_id, p_description
  )
  on conflict do nothing;
end;
$function$

CREATE OR REPLACE FUNCTION private.cancel_event_registration_impl(p_registration_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_event_id uuid;
begin
  if (select auth.uid()) is null then raise exception 'Guardian household access required'; end if;
  select event_id into v_event_id from public.event_registrations
  where id=p_registration_id and private.can_manage_household(household_id);
  if not found then raise exception 'Registration not found'; end if;
  -- Match registration's lock order so cancellation cannot race its seat count.
  perform 1 from public.events where id=v_event_id for update;
  update public.event_registrations set status='canceled',canceled_at=coalesce(canceled_at,now())
  where id=p_registration_id and private.can_manage_household(household_id)
    and status in ('registered','waitlist','canceled');
  if not found then raise exception 'Registration cannot be canceled'; end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.claim_marketing_leads_for_household_impl(p_household_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := (select auth.uid());
  v_email text;
  v_count integer;
begin
  if v_user_id is null then
    raise exception 'Authentication required';
  end if;

  if not private.can_manage_household(p_household_id) then
    raise exception 'Guardian household access required';
  end if;

  select lower(email) into v_email
  from auth.users
  where id=v_user_id;

  if v_email is null then
    return 0;
  end if;

  update public.marketing_leads
  set converted_user_id=v_user_id,
      converted_household_id=p_household_id,
      converted_at=coalesce(converted_at,now()),
      metadata=metadata||jsonb_build_object(
        'converted_to_adventure_club',true,
        'converted_at',now()
      )
  where lower(email)=v_email
    and (
      converted_user_id is null
      or converted_user_id=v_user_id
    );

  get diagnostics v_count = row_count;
  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION private.create_group_join_code_impl(p_group_id uuid, p_expires_in_days integer, p_max_uses integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_code text;
begin
  if not private.can_lead_group(p_group_id) then
    raise exception 'Group leader access required';
  end if;

  if p_expires_in_days is null or p_expires_in_days < 1 or p_expires_in_days > 90 then
    raise exception 'Expiration must be between 1 and 90 days';
  end if;

  v_code := upper(encode(extensions.gen_random_bytes(5),'hex'));

  insert into private.group_join_codes(
    group_id,code_hash,expires_at,max_uses,created_by
  )
  values(
    p_group_id,
    encode(extensions.digest(v_code,'sha256'),'hex'),
    now()+make_interval(days=>p_expires_in_days),
    p_max_uses,
    (select auth.uid())
  );

  return v_code;
end;
$function$

CREATE OR REPLACE FUNCTION private.create_guardian_unlock_session_impl(p_household_id uuid, p_pin text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_token text;
begin
  if not private.verify_guardian_pin_impl(p_household_id,p_pin) then
    -- A normal NULL response commits the attempt/lockout changes.
    -- Raising here would roll back the verifier's security state.
    return null;
  end if;

  update private.guardian_unlock_sessions
  set revoked_at=clock_timestamp()
  where household_id=p_household_id
    and user_id=(select auth.uid())
    and revoked_at is null;

  v_token := encode(extensions.gen_random_bytes(32),'hex');

  insert into private.guardian_unlock_sessions(
    household_id,user_id,token_hash,expires_at
  )
  values(
    p_household_id,
    (select auth.uid()),
    encode(extensions.digest(v_token,'sha256'),'hex'),
    clock_timestamp()+interval '30 minutes'
  );

  return v_token;
end;
$function$

CREATE OR REPLACE FUNCTION private.create_household_invitation_impl(p_household_id uuid, p_email text, p_role text, p_expires_days integer)
 RETURNS TABLE(invitation_id uuid, invitation_token text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_token text;
  v_email text;
begin
  if not private.can_manage_household(p_household_id) then
    raise exception 'Guardian access required';
  end if;

  if p_role not in ('parent','guardian','adult') then
    raise exception 'Invalid household role';
  end if;

  v_email := lower(trim(p_email));
  if v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'Valid email required';
  end if;

  if exists (
    select 1
    from public.household_members hm
    join auth.users u on u.id=hm.user_id
    where hm.household_id=p_household_id
      and hm.status='active'
      and lower(u.email)=v_email
  ) then
    raise exception 'That adult is already part of this household';
  end if;

  update public.household_invitations
  set status='revoked'
  where household_id=p_household_id
    and lower(email)=v_email
    and status='pending';

  v_token := encode(extensions.gen_random_bytes(24),'hex');

  insert into public.household_invitations(
    household_id,email,role,invited_by,status,expires_at
  )
  values(
    p_household_id,
    v_email,
    p_role,
    (select auth.uid()),
    'pending',
    now() + make_interval(days=>greatest(coalesce(p_expires_days,7),1))
  )
  returning id into v_id;

  insert into private.household_invitation_tokens(invitation_id,token_hash)
  values(v_id,extensions.digest(v_token,'sha256'));

  return query select v_id,v_token;
end;
$function$

CREATE OR REPLACE FUNCTION private.create_organization_invitation_impl(p_organization_id uuid, p_email text, p_organization_role text, p_group_id uuid, p_group_role text, p_expires_in_days integer)
 RETURNS TABLE(invitation_id uuid, invitation_token text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_token text;
  v_invitation_id uuid;
begin
  if not private.can_manage_org(p_organization_id) then
    raise exception 'Organization admin access required';
  end if;

  if p_organization_role not in ('admin','leader','viewer') then
    raise exception 'Unsupported organization role';
  end if;

  if p_organization_role='leader' and p_group_id is null then
    raise exception 'Leader invitations must be assigned to a specific group';
  end if;

  if p_expires_in_days is null
     or p_expires_in_days<1
     or p_expires_in_days>30 then
    raise exception 'Invitation expiration must be between 1 and 30 days';
  end if;

  if p_group_id is not null then
    if not exists(
      select 1
      from public.adventure_groups ag
      where ag.id=p_group_id
        and ag.organization_id=p_organization_id
        and ag.status='active'
    ) then
      raise exception 'Group does not belong to this organization';
    end if;

    if p_group_role is null then
      p_group_role := 'leader';
    end if;
  end if;

  update public.organization_invitations
  set status='canceled'
  where organization_id=p_organization_id
    and lower(email)=lower(trim(p_email))
    and status='invited';

  v_token := encode(extensions.gen_random_bytes(24),'hex');

  insert into public.organization_invitations(
    organization_id,email,organization_role,group_id,group_role,
    status,invited_by,expires_at
  )
  values(
    p_organization_id,
    lower(trim(p_email)),
    p_organization_role,
    p_group_id,
    case when p_group_id is null then null else coalesce(p_group_role,'leader') end,
    'invited',
    (select auth.uid()),
    now()+make_interval(days=>p_expires_in_days)
  )
  returning id into v_invitation_id;

  insert into private.organization_invitation_tokens(
    invitation_id,token_hash
  )
  values(
    v_invitation_id,
    encode(extensions.digest(v_token,'sha256'),'hex')
  );

  return query select v_invitation_id,v_token;
end;
$function$

CREATE OR REPLACE FUNCTION private.dc_entity_fingerprint(p_entity_type text, p_entity_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_payload jsonb;
begin
  v_payload := private.dc_entity_payload(p_entity_type,p_entity_id);
  if v_payload is null then return null; end if;

  if p_entity_type <> 'product' then
    v_payload := v_payload
      - array['created_at','updated_at','status','available_from','available_until','is_featured']::text[];
  end if;

  return encode(extensions.digest(v_payload::text,'sha256'),'hex');
end;
$function$

CREATE OR REPLACE FUNCTION private.dc_entity_payload(p_entity_type text, p_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_payload jsonb;
begin
  case p_entity_type
    when 'book' then select to_jsonb(t) into v_payload from public.books t where t.id=p_entity_id;
    when 'adventure' then select to_jsonb(t) into v_payload from public.adventures t where t.id=p_entity_id;
    when 'challenge' then select to_jsonb(t) into v_payload from public.challenges t where t.id=p_entity_id;
    when 'content_item' then select to_jsonb(t) into v_payload from public.content_items t where t.id=p_entity_id;
    when 'scripture_passage' then select to_jsonb(t) into v_payload from public.scripture_passages t where t.id=p_entity_id;
    when 'power_verse' then select to_jsonb(t) into v_payload from public.power_verses t where t.id=p_entity_id;
    when 'devotional_series' then select to_jsonb(t) into v_payload from public.devotional_series t where t.id=p_entity_id;
    when 'prayer_prompt' then select to_jsonb(t) into v_payload from public.prayer_prompts t where t.id=p_entity_id;
    when 'identity_truth' then select to_jsonb(t) into v_payload from public.identity_truths t where t.id=p_entity_id;
    when 'family_faith_guide' then select to_jsonb(t) into v_payload from public.family_faith_guides t where t.id=p_entity_id;
    when 'event' then select to_jsonb(t) into v_payload from public.events t where t.id=p_entity_id;
    when 'media_asset' then select to_jsonb(t) into v_payload from public.media_assets t where t.id=p_entity_id;
    when 'product' then
      select jsonb_build_object(
        'name',t.name,
        'product_type',t.product_type,
        'description',t.description,
        'image_asset_key',t.image_asset_key,
        'metadata',t.metadata
      )
      into v_payload
      from public.products t
      where t.id=p_entity_id;
    else raise exception 'Unsupported DC governance entity type: %',p_entity_type;
  end case;
  return v_payload;
end;
$function$

CREATE OR REPLACE FUNCTION private.demote_changed_dc_content()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_public_statuses text[] := string_to_array(tg_argv[0],',');
  v_old_status text := to_jsonb(old)->>'status';
  v_new_status text := to_jsonb(new)->>'status';
begin
  if v_old_status = any(v_public_statuses)
     and v_new_status = any(v_public_statuses)
     and private.dc_row_fingerprint(to_jsonb(old))
       is distinct from private.dc_row_fingerprint(to_jsonb(new)) then
    new.status := 'draft';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.demote_changed_dc_product()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_old jsonb;
  v_new jsonb;
begin
  if old.status='active' and new.status='active' then
    v_old := jsonb_build_object(
      'name',old.name,'product_type',old.product_type,'description',old.description,
      'image_asset_key',old.image_asset_key,'metadata',old.metadata
    );
    v_new := jsonb_build_object(
      'name',new.name,'product_type',new.product_type,'description',new.description,
      'image_asset_key',new.image_asset_key,'metadata',new.metadata
    );

    if v_old is distinct from v_new then
      new.status := 'draft';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.digital_book_manifest_valid(p_book_id uuid, p_manifest jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare page jsonb; paths text[] := '{}'; prefix text;
begin
  if p_book_id is null or p_manifest is null or jsonb_typeof(p_manifest) <> 'object'
    or coalesce(p_manifest->>'revision','') !~ '^[a-z0-9][a-z0-9-]{0,63}$'
    or jsonb_typeof(p_manifest->'pages') is distinct from 'array' then return false; end if;
  if jsonb_array_length(p_manifest->'pages') not between 1 and 300 then return false; end if;
  prefix := p_book_id::text || '/' || (p_manifest->>'revision') || '/';
  for page in select value from jsonb_array_elements(p_manifest->'pages') loop
    if jsonb_typeof(page) <> 'object'
      or jsonb_typeof(page->'path') is distinct from 'string'
      or left(page->>'path',length(prefix)) <> prefix
      or substring(page->>'path' from length(prefix)+1) !~ '^[a-zA-Z0-9_-]+\.(png|jpg|jpeg|webp)$'
      or jsonb_typeof(page->'alt') is distinct from 'string'
      or length(btrim(page->>'alt')) not between 1 and 10000
      or (page->>'alt') like '%' || chr(8212) || '%'
      or (page->>'path') = any(paths) then return false; end if;
    paths := array_append(paths,page->>'path');
  end loop;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION private.digital_book_object_readable(p_path text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target_book_id uuid;
begin
  if (select auth.uid()) is null then return false; end if;
  begin target_book_id:=split_part(p_path,'/',1)::uuid;
  exception when invalid_text_representation then return false; end;
  return private.digital_book_released(target_book_id)
    and exists (select 1 from private.digital_book_manifests m, jsonb_array_elements(m.manifest->'pages') page
      where m.book_id=target_book_id and page->>'path'=p_path)
    and exists (select 1 from public.child_profiles cp
      join public.household_members hm on hm.household_id=cp.household_id
      where hm.user_id=(select auth.uid()) and hm.status='active' and hm.role in ('owner','parent','guardian')
        and cp.status='active' and private.child_has_digital_book_access(cp.id,target_book_id));
end;
$function$

CREATE OR REPLACE FUNCTION private.enforce_dc_prayer_opening()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_field text := tg_argv[0];
  v_prayer text;
begin
  v_prayer := to_jsonb(new) ->> v_field;

  if v_prayer is not null and btrim(v_prayer) <> '' then
    if btrim(v_prayer) ~* '^Dear[[:space:]]+Jesus([,[:space:]]|$)' then
      raise exception 'Dustin Courageous prayers must be addressed to God, not Jesus. Begin with "Dear God,".';
    end if;

    if btrim(v_prayer) !~* '^Dear[[:space:]]+God[[:space:]]*,' then
      raise exception 'Dustin Courageous prayers must begin with "Dear God,".';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.enforce_dc_publish_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_entity_type text := tg_argv[0];
  v_publish_statuses text[] := string_to_array(tg_argv[1],',');
  v_new_status text;
begin
  v_new_status := to_jsonb(new)->>'status';

  if v_new_status = any(v_publish_statuses) then
    if not private.has_approved_dc_review(v_entity_type,new.id) then
      raise exception 'DC governance review is required before publishing this %.',replace(v_entity_type,'_',' ');
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.get_digital_book_impl(p_child_profile_id uuid, p_book_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare content jsonb; position integer;
begin
  if (select auth.uid()) is null or not private.can_manage_child(p_child_profile_id)
    or not exists (select 1 from public.child_profiles where id=p_child_profile_id and status='active') then
    raise exception 'Child access denied' using errcode='42501';
  end if;
  if not private.digital_book_released(p_book_id) then return jsonb_build_object('availability','unavailable'); end if;
  if not private.child_has_digital_book_access(p_child_profile_id,p_book_id) then return jsonb_build_object('availability','locked'); end if;
  select manifest into content from private.digital_book_manifests where book_id=p_book_id;
  select page_number into position from public.child_book_reading_positions
    where child_profile_id=p_child_profile_id and book_id=p_book_id and revision=content->>'revision';
  return jsonb_build_object('availability','ready','revision',content->>'revision','pages',content->'pages',
    'page_number',least(coalesce(position,1),jsonb_array_length(content->'pages')));
end;
$function$

CREATE OR REPLACE FUNCTION private.get_or_create_referral_code_impl(p_household_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_code text;
begin
  if not private.can_manage_household(p_household_id) then
    raise exception 'Guardian household access required';
  end if;

  select code into v_code
  from public.referral_codes
  where household_id=p_household_id and is_active=true;

  if v_code is not null then
    return v_code;
  end if;

  loop
    v_code := upper(substr(encode(extensions.gen_random_bytes(6),'hex'),1,10));
    exit when not exists(select 1 from public.referral_codes where code=v_code);
  end loop;

  insert into public.referral_codes(household_id,code,created_by)
  values(p_household_id,v_code,(select auth.uid()));

  return v_code;
end;
$function$

CREATE OR REPLACE FUNCTION private.initialize_household()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_free_plan_id uuid;
begin
  if new.created_by is null then
    raise exception 'Household creator is required';
  end if;

  insert into public.household_members (household_id, user_id, role, status)
  values (new.id, new.created_by, 'owner', 'active')
  on conflict (household_id, user_id) do nothing;

  select id into v_free_plan_id
  from public.membership_plans
  where plan_key = 'free' and is_active = true
  limit 1;

  if v_free_plan_id is not null then
    insert into public.household_subscriptions
      (household_id, plan_id, status, provider, metadata)
    select new.id, v_free_plan_id, 'active', null, '{"system_assigned":true}'::jsonb
    where not exists (
      select 1 from public.household_subscriptions hs
      where hs.household_id = new.id
    );
  end if;

  insert into public.notification_preferences (user_id, timezone)
  values (new.created_by, new.timezone)
  on conflict (user_id) do nothing;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.invoke_notification_delivery_worker()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_project_url text;
  v_worker_token text;
  v_request_id bigint;
begin
  select decrypted_secret into v_project_url
  from vault.decrypted_secrets
  where name='dc_project_url'
  limit 1;

  select decrypted_secret into v_worker_token
  from vault.decrypted_secrets
  where name='dc_notification_delivery_worker_token'
  limit 1;

  if v_project_url is null or v_worker_token is null then
    raise exception 'Notification worker Vault configuration is incomplete';
  end if;

  select net.http_post(
    url := v_project_url || '/functions/v1/notification-delivery-worker-v2',
    headers := jsonb_build_object(
      'Content-Type','application/json',
      'x-dc-worker-token',v_worker_token
    ),
    body := jsonb_build_object('limit',100),
    timeout_milliseconds := 10000
  )
  into v_request_id;

  return v_request_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.join_child_to_group_impl(p_code text, p_child_profile_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_join_code private.group_join_codes%rowtype;
  v_group_id uuid;
  v_household_id uuid;
  v_policy_version text;
begin
  if (select auth.uid()) is null or not private.can_manage_child(p_child_profile_id) then
    raise exception 'Guardian access required';
  end if;

  select cp.household_id
    into v_household_id
  from public.child_profiles cp
  where cp.id=p_child_profile_id and cp.status='active'
  for update;

  if not found then
    raise exception 'Active child profile required';
  end if;

  select *
    into v_join_code
  from private.group_join_codes
  where code_hash=encode(
      extensions.digest(upper(trim(p_code)),'sha256'),'hex'
    )
    and is_active=true
    and expires_at>now()
  for update;

  if not found then
    raise exception 'Join code is invalid, expired, or full';
  end if;

  if not exists(
    select 1
    from public.adventure_groups ag
    join public.organizations o on o.id=ag.organization_id
    where ag.id=v_join_code.group_id
      and ag.status='active'
      and o.status='active'
  ) then
    raise exception 'Group is not active';
  end if;

  -- The child lock serializes joins through different codes and withdrawal.
  -- An already-active membership does not consume another use or rewrite approval.
  if exists (
    select 1 from public.child_group_memberships
    where group_id=v_join_code.group_id and child_profile_id=p_child_profile_id
      and status='active'
  ) then
    return v_join_code.group_id;
  end if;

  if v_join_code.max_uses is not null and v_join_code.use_count>=v_join_code.max_uses then
    raise exception 'Join code is invalid, expired, or full';
  end if;

  select current_policy_version into v_policy_version
  from public.consent_policies
  where consent_key='group_participation' and is_active=true;
  if v_policy_version is null then
    raise exception 'Group participation consent is unavailable';
  end if;

  insert into public.child_group_memberships(
    group_id,child_profile_id,status,
    guardian_approved_by,guardian_approved_at,joined_at
  )
  values(
    v_join_code.group_id,
    p_child_profile_id,
    'active',
    (select auth.uid()),
    now(),
    now()
  )
  on conflict(group_id,child_profile_id) do update
  set status='active',
      guardian_approved_by=(select auth.uid()),
      guardian_approved_at=now(),
      joined_at=now(),
      ended_at=null;

  if v_policy_version is not null
     and not exists (
       select 1
       from public.current_household_consents chc
       where chc.household_id=v_household_id
         and chc.child_profile_id=p_child_profile_id
         and chc.consent_key='group_participation'
         and chc.action='granted'
         and chc.policy_version=v_policy_version
     ) then
    insert into public.household_consents(
      household_id,guardian_user_id,child_profile_id,
      consent_key,action,policy_version,metadata
    )
    values(
      v_household_id,
      (select auth.uid()),
      p_child_profile_id,
      'group_participation',
      'granted',
      v_policy_version,
      jsonb_build_object(
        'surface','group_join',
        'group_id',v_join_code.group_id
      )
    );
  end if;

  update private.group_join_codes
  set use_count=use_count+1
  where id=v_join_code.id;

  v_group_id:=v_join_code.group_id;
  return v_group_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.notification_next_delivery_at(p_user_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_timezone text := 'America/Chicago';
  v_start time;
  v_end time;
  v_local_now timestamp;
  v_local_date date;
  v_local_time time;
  v_next_local timestamp;
begin
  select
    coalesce(np.timezone,'America/Chicago'),
    np.quiet_hours_start,
    np.quiet_hours_end
  into v_timezone,v_start,v_end
  from public.notification_preferences np
  where np.user_id=p_user_id;

  if v_start is null or v_end is null or v_start=v_end then
    return now();
  end if;

  v_local_now := timezone(v_timezone,now());
  v_local_date := v_local_now::date;
  v_local_time := v_local_now::time;

  if v_start < v_end then
    if v_local_time >= v_start and v_local_time < v_end then
      v_next_local := v_local_date + v_end;
      return v_next_local at time zone v_timezone;
    end if;
  else
    if v_local_time >= v_start then
      v_next_local := (v_local_date+1) + v_end;
      return v_next_local at time zone v_timezone;
    elsif v_local_time < v_end then
      v_next_local := v_local_date + v_end;
      return v_next_local at time zone v_timezone;
    end if;
  end if;

  return now();
end;
$function$

CREATE OR REPLACE FUNCTION private.prevent_book_progress_regression()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.status = 'adventure_completed' and new.status <> 'adventure_completed' then
    raise exception 'A completed Book Adventure cannot be restarted';
  end if;

  if old.status = 'completed' and new.status in ('available', 'reading') then
    raise exception 'A completed book cannot be restarted';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.prevent_completed_progress_reversal()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.status = 'completed' and new.status <> 'completed' and not private.is_app_admin() then
    raise exception 'Completed progress cannot be reversed';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.process_book_progress()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_xp integer;
  v_title text;
  v_household_id uuid;
begin
  if new.status not in ('completed','adventure_completed') then
    return new;
  end if;

  if tg_op='UPDATE' and old.status in ('completed','adventure_completed') then
    if old.status='adventure_completed' or new.status=old.status then
      return new;
    end if;
  end if;

  select b.completion_xp, b.title, cp.household_id
    into v_xp, v_title, v_household_id
  from public.books b
  join public.child_profiles cp on cp.id=new.child_profile_id
  where b.id=new.book_id;

  if new.status='completed' and new.completed_at is null then
    update public.child_book_progress
    set completed_at=now()
    where id=new.id and completed_at is null;
  elsif new.status='adventure_completed' and new.adventure_completed_at is null then
    update public.child_book_progress
    set completed_at=coalesce(completed_at,now()),
        adventure_completed_at=now()
    where id=new.id and adventure_completed_at is null;
  end if;

  if new.status='completed' then
    perform private.award_xp_event(
      new.child_profile_id, v_xp, 'book_completed',
      'book', new.book_id, v_title
    );

    insert into public.child_activity_events (
      child_profile_id, household_id, event_type, title, description, source_type, source_id, xp_delta
    )
    values (
      new.child_profile_id, v_household_id, 'book_completed',
      'Book completed', v_title, 'book', new.book_id, coalesce(v_xp,0)
    );
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.process_content_completed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_xp integer;
  v_title text;
  v_household_id uuid;
begin
  if new.status <> 'completed'
     or (tg_op='UPDATE' and old.status='completed') then
    return new;
  end if;

  select ci.completion_xp,ci.title,cp.household_id
    into v_xp,v_title,v_household_id
  from public.content_items ci
  join public.child_profiles cp on cp.id=new.child_profile_id
  where ci.id=new.content_item_id;

  if new.completed_at is null then
    update public.child_content_progress
    set completed_at=now()
    where id=new.id and completed_at is null;
  end if;

  perform private.award_xp_event(
    new.child_profile_id,v_xp,'content_completed',
    'content_item',new.content_item_id,v_title
  );

  insert into public.child_activity_events(
    child_profile_id,household_id,event_type,title,description,source_type,source_id,xp_delta
  )
  values(
    new.child_profile_id,v_household_id,'content_completed',
