CREATE OR REPLACE FUNCTION private.sync_reward_redemption_fulfillment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_reward_id uuid;
  v_reward_type text;
  v_inventory integer;
begin
  if new.status = 'fulfilled'
     and old.status is distinct from 'fulfilled' then

    select r.id, r.reward_type, r.inventory_quantity
      into v_reward_id, v_reward_type, v_inventory
    from public.reward_unlocks ru
    join public.rewards r on r.id = ru.reward_id
    where ru.id = new.reward_unlock_id
    for update of r;

    if v_reward_id is null then
      raise exception 'Reward could not be resolved';
    end if;

    if v_reward_type = 'physical' and v_inventory is not null then
      if v_inventory <= 0 then
        raise exception 'Reward is out of stock';
      end if;

      update public.rewards
      set inventory_quantity = inventory_quantity - 1
      where id = v_reward_id;
    end if;

    new.fulfilled_at := coalesce(new.fulfilled_at, now());

    update public.reward_unlocks
      set redeemed_at = coalesce(redeemed_at, now())
    where id = new.reward_unlock_id;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.validate_challenge_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_required integer;
  v_completed integer;
  v_parent_approval boolean;
  v_guardian_verified boolean;
begin
  if new.status='completed'
     and (tg_op='INSERT' or old.status is distinct from 'completed') then

    select parent_approval_required
      into v_parent_approval
    from public.challenges
    where id=new.challenge_id;

    select count(*)
      into v_required
    from public.challenge_steps
    where challenge_id=new.challenge_id
      and is_required=true;

    if v_required>0 then
      select count(*)
        into v_completed
      from public.child_step_progress csp
      join public.challenge_steps cs
        on cs.id=csp.challenge_step_id
      where csp.child_challenge_progress_id=new.id
        and cs.challenge_id=new.challenge_id
        and cs.is_required=true
        and csp.completed=true;

      if v_completed<v_required then
        raise exception 'Required challenge steps are incomplete';
      end if;
    end if;

    if v_parent_approval then
      v_guardian_verified :=
        coalesce(
          current_setting(
            'dc.guardian_approval_verified',
            true
          ),
          'false'
        )='true';

      if not v_guardian_verified then
        raise exception 'Guardian PIN approval is required';
      end if;

      if not private.can_manage_child(new.child_profile_id) then
        raise exception 'Guardian approval is required';
      end if;

      new.approved_by:=(select auth.uid());
      new.approved_at:=now();
    end if;

    if new.completed_at is null then
      new.completed_at:=now();
    end if;
  end if;

  return new;
end;
$function$

