CREATE OR REPLACE FUNCTION private.validate_reward_redemption_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.status = new.status then
    return new;
  end if;

  if old.status in ('fulfilled','denied','canceled') then
    raise exception 'A finalized redemption cannot be reopened';
  end if;

  if old.status = 'requested' and new.status not in ('approved','denied','canceled') then
    raise exception 'Invalid redemption status transition';
  end if;

  if old.status = 'approved' and new.status not in ('processing','fulfilled','denied','canceled') then
    raise exception 'Invalid redemption status transition';
  end if;

  if old.status = 'processing' and new.status not in ('fulfilled','denied','canceled') then
    raise exception 'Invalid redemption status transition';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.verify_guardian_pin_impl(p_household_id uuid, p_pin text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row private.household_guardian_security%rowtype;
  v_next_attempts integer;
  v_now timestamptz;
begin
  if not private.can_manage_household(p_household_id) then
    return false;
  end if;

  select *
    into v_row
  from private.household_guardian_security
  where household_id = p_household_id
  for update;

  if not found then
    return false;
  end if;

  -- Evaluate time after the row lock: concurrent requests serialize here.
  v_now := clock_timestamp();
  if v_row.locked_until is not null and v_row.locked_until > v_now then
    return false;
  end if;

  if extensions.crypt(p_pin, v_row.pin_hash) = v_row.pin_hash then
    update private.household_guardian_security
    set failed_attempts = 0,
        locked_until = null,
        updated_at = v_now
    where household_id = p_household_id;
    return true;
  end if;

  v_next_attempts := v_row.failed_attempts + 1;

  update private.household_guardian_security
  set failed_attempts =
        case when v_next_attempts >= 5 then 0 else v_next_attempts end,
      locked_until =
        case when v_next_attempts >= 5 then v_now + interval '15 minutes' else null end,
      updated_at = v_now
  where household_id = p_household_id;

  return false;
end;
$function$

