CREATE OR REPLACE FUNCTION public.admin_create_lifetime_badge_level(p_badge_key text, p_name text, p_rule_type text, p_threshold_value integer DEFAULT NULL::integer, p_description text DEFAULT NULL::text, p_badge_family_key text DEFAULT NULL::text, p_tier text DEFAULT NULL::text, p_rarity text DEFAULT 'standard'::text, p_streak_key text DEFAULT NULL::text, p_challenge_type text DEFAULT NULL::text, p_token_type text DEFAULT NULL::text, p_activity_event_type text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_badge_id uuid;
begin
  if not private.is_content_admin() then
    raise exception 'Content administrator access required';
  end if;

  if p_rule_type not in (
    'xp_threshold','challenge_count','adventure_count',
    'streak','challenge_type_count','token_threshold',
    'activity_event_count','manual'
  ) then
    raise exception 'Unsupported achievement rule';
  end if;

  if p_rule_type <> 'manual'
    and (p_threshold_value is null or p_threshold_value <= 0) then
    raise exception 'Threshold must be greater than zero';
  end if;

  if p_rule_type='token_threshold'
    and nullif(trim(p_token_type),'') is null then
    raise exception 'Token type is required';
  end if;

  if p_rule_type='activity_event_count'
    and nullif(trim(p_activity_event_type),'') is null then
    raise exception 'Activity event type is required';
  end if;

  insert into public.badges(
    badge_key,name,description,rarity,badge_scope,badge_tier,badge_family_key,is_active
  )
  values(
    trim(p_badge_key),trim(p_name),nullif(trim(p_description),''),
    p_rarity,'lifetime',p_tier,
    coalesce(nullif(trim(p_badge_family_key),''),trim(p_badge_key)),
    true
  )
  returning id into v_badge_id;

  insert into public.badge_rules(
    badge_id,rule_type,threshold_value,streak_key,challenge_type,
    token_type,activity_event_type,is_active
  )
  values(
    v_badge_id,
    p_rule_type,
    case when p_rule_type='manual' then null else p_threshold_value end,
    case when p_rule_type='streak' then p_streak_key else null end,
    case when p_rule_type='challenge_type_count' then p_challenge_type else null end,
    case when p_rule_type='token_threshold' then trim(p_token_type) else null end,
    case when p_rule_type='activity_event_count' then trim(p_activity_event_type) else null end,
    true
  );

  return v_badge_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_create_notification_reminder_rule(p_rule_key text, p_name text, p_rule_type text, p_template_id uuid, p_lead_minutes integer, p_delivery_channels text[] DEFAULT NULL::text[], p_organization_id uuid DEFAULT NULL::uuid, p_group_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_template_channels text[];
begin
  if not private.can_schedule_notifications() then
    raise exception 'Notification scheduling access required';
  end if;

  select default_channels
    into v_template_channels
  from public.notification_templates
  where id=p_template_id
    and status='active';

  if v_template_channels is null then
    raise exception 'Reminder template must be active and DC-approved.';
  end if;

  if p_rule_type not in ('event_upcoming','group_challenge_due') then
    raise exception 'Unsupported reminder rule type';
  end if;

  if p_group_id is not null
     and p_organization_id is not null
     and not exists (
       select 1
       from public.adventure_groups ag
       where ag.id=p_group_id
         and ag.organization_id=p_organization_id
     ) then
    raise exception 'Group does not belong to the selected organization';
  end if;

  insert into public.notification_reminder_rules(
    rule_key,name,rule_type,template_id,lead_minutes,
    organization_id,group_id,delivery_channels,status,created_by
  )
  values(
    trim(p_rule_key),
    trim(p_name),
    p_rule_type,
    p_template_id,
    p_lead_minutes,
    p_organization_id,
    p_group_id,
    coalesce(p_delivery_channels,v_template_channels),
    'active',
    (select auth.uid())
  )
  returning id into v_id;

  return v_id;
end;
$function$

