CREATE OR REPLACE FUNCTION public.create_checkout_order(p_household_id uuid, p_items jsonb, p_promo_code text DEFAULT NULL::text)
 RETURNS TABLE(checkout_session_id uuid, order_id uuid, order_number bigint, subtotal_cents integer, discount_cents integer, total_cents integer, currency text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := (select auth.uid());
  v_order_id uuid;
  v_order_number bigint;
  v_session_id uuid;
  v_expires_at timestamptz := now()+interval '30 minutes';
  v_item jsonb;
  v_product public.products%rowtype;
  v_variant public.product_variants%rowtype;
  v_quantity integer;
  v_variant_id uuid;
  v_unit_price integer;
  v_line_total integer;
  v_subtotal integer := 0;
  v_discount integer := 0;
  v_total integer := 0;
  v_is_paid_member boolean;
  v_reserved integer;
  v_available integer;
  v_promo public.promo_codes%rowtype;
  v_promo_id uuid;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  if not private.can_manage_household(p_household_id) then
    raise exception 'Guardian household access required';
  end if;
  if jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items)=0
     or jsonb_array_length(p_items)>25 then
    raise exception 'Checkout must contain between 1 and 25 line items';
  end if;

  v_is_paid_member := private.household_is_paid_member(p_household_id);

  insert into public.orders(
    household_id,purchaser_user_id,status,currency,billing_email,metadata
  )
  select
    p_household_id,v_user_id,'draft','USD',u.email,
    jsonb_build_object('checkout_source','adventure_club')
  from auth.users u
  where u.id=v_user_id
  returning id,order_number into v_order_id,v_order_number;

  insert into public.checkout_sessions(
    order_id,household_id,user_id,status,expires_at
  )
  values(v_order_id,p_household_id,v_user_id,'created',v_expires_at)
  returning id into v_session_id;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    if (v_item->>'product_id') is null then
      raise exception 'Every checkout item requires product_id';
    end if;

    v_quantity := greatest(coalesce((v_item->>'quantity')::integer,1),1);
    if v_quantity>20 then raise exception 'Maximum quantity per line is 20'; end if;

    select * into v_product
    from public.products
    where id=(v_item->>'product_id')::uuid
      and status='active'
    for share;

    if not found then raise exception 'Product unavailable'; end if;

    v_variant_id := nullif(v_item->>'variant_id','')::uuid;

    if v_variant_id is not null then
      select * into v_variant
      from public.product_variants
      where id=v_variant_id
        and product_id=v_product.id
        and is_active=true
      for share;

      if not found then raise exception 'Product variant unavailable'; end if;
    else
      v_variant := null;
    end if;

    v_unit_price :=
      case
        when v_is_paid_member and v_product.member_price_cents is not null
          then v_product.member_price_cents
        else v_product.base_price_cents
      end
      + case
          when v_variant_id is null then 0
          when v_is_paid_member then coalesce(v_variant.member_price_delta_cents,0)
          else coalesce(v_variant.price_delta_cents,0)
        end;

    v_unit_price := greatest(v_unit_price,0);
    v_line_total := v_unit_price*v_quantity;
    v_subtotal := v_subtotal+v_line_total;

    if v_variant_id is not null and v_variant.track_inventory and v_variant.inventory_quantity is not null then
      select coalesce(sum(ir.quantity),0)::integer into v_reserved
      from public.inventory_reservations ir
      where ir.product_variant_id=v_variant_id
        and ir.released_at is null
        and ir.expires_at>now();

      v_available := v_variant.inventory_quantity-v_reserved;
      if v_available < v_quantity and not v_product.allow_backorder then
        raise exception 'Insufficient inventory for %',v_variant.name;
      end if;
    elsif v_product.track_inventory and v_product.inventory_quantity is not null then
      select coalesce(sum(ir.quantity),0)::integer into v_reserved
      from public.inventory_reservations ir
      where ir.product_id=v_product.id
        and ir.product_variant_id is null
        and ir.released_at is null
        and ir.expires_at>now();

      v_available := v_product.inventory_quantity-v_reserved;
      if v_available < v_quantity and not v_product.allow_backorder then
        raise exception 'Insufficient inventory for %',v_product.name;
      end if;
    end if;

    insert into public.order_items(
      order_id,product_id,product_variant_id,quantity,unit_price_cents,
      discount_cents,line_total_cents,product_name_snapshot,
      variant_name_snapshot,sku_snapshot
    )
    values(
      v_order_id,v_product.id,v_variant_id,v_quantity,v_unit_price,
      0,v_line_total,v_product.name,
      case when v_variant_id is null then null else v_variant.name end,
      coalesce(case when v_variant_id is null then null else v_variant.sku end,v_product.sku)
    );

    if (v_variant_id is not null and v_variant.track_inventory and v_variant.inventory_quantity is not null)
       or (v_variant_id is null and v_product.track_inventory and v_product.inventory_quantity is not null) then
      insert into public.inventory_reservations(
        checkout_session_id,product_id,product_variant_id,quantity,expires_at
      )
      values(v_session_id,v_product.id,v_variant_id,v_quantity,v_expires_at);
    end if;
  end loop;

  if nullif(trim(p_promo_code),'') is not null then
    select * into v_promo
    from public.promo_codes
    where upper(code)=upper(trim(p_promo_code))
      and is_active=true
      and (starts_at is null or starts_at<=now())
      and (ends_at is null or ends_at>now())
      and (max_redemptions is null or redemption_count<max_redemptions)
    for update;

    if not found then raise exception 'Promo code is invalid or expired'; end if;
    if v_subtotal < v_promo.minimum_order_cents then
      raise exception 'Order does not meet the promo code minimum';
    end if;

    v_discount := case
      when v_promo.discount_type='percent'
        then floor(v_subtotal*(least(v_promo.discount_value,100)::numeric/100))::integer
      else least(v_promo.discount_value,v_subtotal)
    end;
    v_promo_id := v_promo.id;
  end if;

  v_total := greatest(v_subtotal-v_discount,0);

  update public.orders
  set subtotal_cents=v_subtotal,
      discount_cents=v_discount,
      total_cents=v_total,
      promo_code_id=v_promo_id,
      updated_at=now()
  where id=v_order_id;

  return query
  select
    v_session_id,v_order_id,v_order_number,v_subtotal,v_discount,v_total,'USD'::text,v_expires_at;
exception
  when others then
    if v_order_id is not null then
      delete from public.orders where id=v_order_id;
    end if;
    raise;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_child_with_consent(p_household_id uuid, p_display_name text, p_birth_year smallint DEFAULT NULL::smallint)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_child_id uuid;
  v_policy_version text;
begin
  if not private.can_manage_household(p_household_id) then
    raise exception 'Guardian household access required';
  end if;

  select current_policy_version
    into v_policy_version
  from public.consent_policies
  where consent_key='child_participation'
    and is_active=true;

  if v_policy_version is null then
    raise exception 'Child participation consent is unavailable';
  end if;

  insert into public.child_profiles(
    household_id,display_name,birth_year,created_by
  )
  values(
    p_household_id,trim(p_display_name),p_birth_year,(select auth.uid())
  )
  returning id into v_child_id;

  insert into public.household_consents(
    household_id,guardian_user_id,child_profile_id,
    consent_key,action,policy_version,metadata
  )
  values(
    p_household_id,(select auth.uid()),v_child_id,
    'child_participation','granted',v_policy_version,
    '{"surface":"child_onboarding"}'::jsonb
  );

  return v_child_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_household_with_consent(p_name text, p_timezone text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_household_id uuid := gen_random_uuid();
  v_policy_version text;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;
  select current_policy_version into v_policy_version
  from public.consent_policies
  where consent_key='guardian_account_terms' and is_active=true;
  if v_policy_version is null then
    raise exception 'Guardian account terms are unavailable';
  end if;
  -- RETURNING checks SELECT RLS before the AFTER INSERT owner-membership
  -- trigger runs. Allocate the ID first, allowing that trigger to finish.
  insert into public.households(id,name,created_by,timezone)
  values(v_household_id,trim(p_name),(select auth.uid()),
    coalesce(nullif(trim(p_timezone),''),'America/Chicago'));
  insert into public.household_consents(
    household_id,guardian_user_id,child_profile_id,
    consent_key,action,policy_version,metadata
  ) values(
    v_household_id,(select auth.uid()),null,
    'guardian_account_terms','granted',v_policy_version,
    '{"surface":"household_onboarding"}'::jsonb
  );
  return v_household_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.dc_preflight_scan(p_entity_type text, p_entity_id uuid)
 RETURNS TABLE(issue_code text, severity text, message text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_payload jsonb;
  v_text text;
  v_prayer text;
  v_missing integer;
begin
  if not private.is_content_admin() then
    raise exception 'Content administrator access required';
  end if;

  v_payload := private.dc_entity_payload(p_entity_type,p_entity_id);

  if v_payload is null then
    return query
      select 'entity_not_found','error','Content record was not found.';
    return;
  end if;

  v_text := v_payload::text;

  if position('—' in v_text) > 0 then
    return query
      select
        'em_dash','error',
        'DC published copy cannot contain an em dash. Replace it with normal punctuation or an en dash.';
  end if;

  if v_text ~* 'Dear[[:space:]]+Jesus([,[:space:]]|$)' then
    return query
      select
        'prayer_to_jesus','error',
        'Dustin Courageous prayers are addressed to God, not Jesus. Begin the prayer with "Dear God,".';
  end if;

  if p_entity_type='prayer_prompt' then
    select prompt_text into v_prayer
    from public.prayer_prompts
    where id=p_entity_id;

    if v_prayer is null
       or btrim(v_prayer) !~* '^Dear[[:space:]]+God[[:space:]]*,' then
      return query
        select
          'prayer_opening','error',
          'Prayer prompts must begin with "Dear God,".';
    end if;

    if not exists (
      select 1
      from public.prayer_prompts
      where id=p_entity_id
        and scripture_passage_id is not null
    ) then
      return query
        select
          'prayer_scripture_link','warning',
          'Consider linking this guided prayer to a verified Scripture passage.';
    end if;
  end if;

  if p_entity_type='family_faith_guide' then
    if not exists (
      select 1
      from public.family_faith_guides
      where id=p_entity_id
        and scripture_passage_id is not null
    ) then
      return query
        select
          'family_scripture','error',
          'Family Faith guides must include a Scripture connection.';
    end if;

    if not exists (
      select 1
      from public.family_faith_guides
      where id=p_entity_id
        and nullif(btrim(discussion_prompt),'') is not null
    ) then
      return query
        select
          'family_discussion','error',
          'Family Faith guides must include a Talk About It discussion prompt.';
    end if;

    select prayer_prompt into v_prayer
    from public.family_faith_guides
    where id=p_entity_id;

    if v_prayer is null
       or btrim(v_prayer) !~* '^Dear[[:space:]]+God[[:space:]]*,' then
      return query
        select
          'family_prayer_opening','error',
          'Family Faith guides must include a prayer that begins with "Dear God,".';
    end if;

    if not exists (
      select 1
      from public.family_faith_guides
      where id=p_entity_id
        and nullif(btrim(family_action),'') is not null
    ) then
      return query
        select
          'family_action','error',
          'Family Faith guides must include a Do It Together family action.';
    end if;
  end if;

  if p_entity_type='power_verse' then
    if not exists (
      select 1
      from public.power_verses
      where id=p_entity_id
        and scripture_passage_id is not null
    ) then
      return query
        select
          'power_verse_scripture','error',
          'A Power Verse must be linked to a verified Scripture passage.';
    end if;

    if exists (
      select 1
      from public.power_verses
      where id=p_entity_id
        and (
          nullif(btrim(say_it),'') is null
          or nullif(btrim(live_it),'') is null
          or nullif(btrim(give_it_away),'') is null
        )
    ) then
      return query
        select
          'power_verse_identity_actions','warning',
          'Power Verses should normally include Say It, Live It, and Give It Away.';
    end if;
  end if;

  if p_entity_type='identity_truth'
     and not exists (
       select 1
       from public.identity_truths
       where id=p_entity_id
         and scripture_passage_id is not null
     ) then
    return query
      select
        'identity_scripture','warning',
        'Identity truths should normally be anchored to a verified Scripture passage.';
  end if;

  if p_entity_type='devotional_series' then
    if not exists (
      select 1
      from public.devotional_days dd
      where dd.devotional_series_id=p_entity_id
    ) then
      return query
        select
          'devotional_days','error',
          'A devotional series must include at least one devotional day.';
    end if;

    select count(*) into v_missing
    from public.devotional_days dd
    where dd.devotional_series_id=p_entity_id
      and dd.prayer_prompt is not null
      and btrim(dd.prayer_prompt) <> ''
      and btrim(dd.prayer_prompt)
        !~* '^Dear[[:space:]]+God[[:space:]]*,';

    if v_missing > 0 then
      return query
        select
          'devotional_prayer_opening','error',
          format(
            '%s devotional prayer(s) do not begin with "Dear God,".',
            v_missing
          );
    end if;

    if exists (
      select 1
      from public.devotional_days dd
      where dd.devotional_series_id=p_entity_id
        and (
          position('—' in coalesce(dd.title,''))>0
          or position('—' in coalesce(dd.body,''))>0
          or position('—' in coalesce(dd.prayer_prompt,''))>0
          or position('—' in coalesce(dd.action_step,''))>0
        )
    ) then
      return query
        select
          'devotional_em_dash','error',
          'One or more devotional days contain an em dash.';
    end if;

    if exists (
      select 1
      from public.devotional_days dd
      where dd.devotional_series_id=p_entity_id
        and dd.scripture_passage_id is null
    ) then
      return query
        select
          'devotional_scripture','warning',
          'One or more devotional days do not have a linked Scripture passage.';
    end if;

    if exists (
      select 1
      from public.devotional_days dd
      where dd.devotional_series_id=p_entity_id
        and nullif(btrim(dd.action_step),'') is null
    ) then
      return query
        select
          'devotional_action','warning',
          'One or more devotional days do not include a practical action step.';
    end if;
  end if;

  if p_entity_type='challenge'
     and not exists (
       select 1
       from public.challenge_steps cs
       where cs.challenge_id=p_entity_id
     ) then
    return query
      select
        'challenge_steps','warning',
        'Adventure Club challenges should normally include at least one concrete challenge step.';
  end if;

  if p_entity_type='book' then
    if not exists (
      select 1 from public.book_power_verses
      where book_id=p_entity_id
    ) then
      return query
        select
          'book_power_verse','warning',
          'The digital Book Adventure should include at least one linked Power Verse.';
    end if;

    if not exists (
      select 1 from public.book_prayer_prompts
      where book_id=p_entity_id
    ) then
      return query
        select
          'book_prayer','warning',
          'The digital Book Adventure should include a linked prayer.';
    end if;

    if not exists (
      select 1 from public.book_identity_truths
      where book_id=p_entity_id
    ) then
      return query
        select
          'book_identity','warning',
          'The digital Book Adventure should include an identity-in-Christ truth.';
    end if;

    if not exists (
      select 1 from public.book_challenges
      where book_id=p_entity_id
    ) then
      return query
        select
          'book_challenge','warning',
          'The digital Book Adventure should include a practical Courage Challenge.';
    end if;
  end if;

  if p_entity_type='notification_template' then
    if not exists (
      select 1
      from public.notification_templates nt
      where nt.id=p_entity_id
        and nullif(btrim(nt.title),'') is not null
        and nullif(btrim(nt.body),'') is not null
    ) then
      return query
        select
          'notification_copy','error',
          'Guardian notification templates require both a title and message body.';
    end if;

    if exists (
      select 1
      from public.notification_templates nt
      where nt.id=p_entity_id
        and nt.notification_type like 'marketing_%'
        and not (nt.default_channels @> array['email']::text[]
                 or nt.default_channels @> array['push']::text[])
    ) then
      return query
        select
          'marketing_delivery','warning',
          'Marketing templates currently have no external delivery channel selected.';
    end if;
  end if;

  if not exists (
    select 1
    from public.dc_governance_standards s
    where s.standard_key='dc-creative-bible'
      and s.version='2026.1'
      and s.is_active=true
      and s.is_locked=true
  ) then
    return query
      select
        'creative_bible_missing','error',
        'The locked Dustin Courageous Bible v2026.1 governance standard is not active.';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_order_paid_from_provider(p_order_id uuid, p_provider text, p_provider_payment_id text, p_provider_customer_id text DEFAULT NULL::text, p_provider_event_id text DEFAULT NULL::text, p_event_type text DEFAULT 'payment_succeeded'::text, p_shipping_name text DEFAULT NULL::text, p_shipping_address jsonb DEFAULT NULL::jsonb, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_session_id uuid;
  v_checkout public.checkout_sessions%rowtype;
  v_total bigint;
  v_currency text;
  v_promo_id uuid;
  v_previous_status text;
  v_item record;
  v_product public.products%rowtype;
  v_variant public.product_variants%rowtype;
begin
  if nullif(trim(p_provider),'') is null or nullif(trim(p_provider_payment_id),'') is null then
    raise exception 'Provider and payment id are required';
  end if;

  if p_provider_event_id is not null then
    insert into public.payment_webhook_events(
      provider,provider_event_id,event_type,order_id,status,payload
    )
    values(
      p_provider,p_provider_event_id,p_event_type,p_order_id,'processing',coalesce(p_payload,'{}'::jsonb)
    )
    on conflict(provider,provider_event_id) do nothing;

    if not found then return; end if;
  end if;

  -- Cancellation and expiry lock checkout before order. Use the same order.
  select * into v_checkout from public.checkout_sessions
  where order_id=p_order_id for update;
  if not found then raise exception 'Checkout session required for payment confirmation'; end if;

  select status,promo_code_id,total_cents,currency
    into v_previous_status,v_promo_id,v_total,v_currency
  from public.orders
  where id=p_order_id
  for update;

  if not found then raise exception 'Order not found'; end if;

  if v_previous_status='paid' then
    if p_provider_event_id is not null then
      update public.payment_webhook_events
      set status='ignored',processed_at=now()
      where provider=p_provider and provider_event_id=p_provider_event_id;
    end if;
    return;
  end if;

  if v_previous_status <> 'pending_payment' then
    raise exception 'Order cannot transition to paid from status %',v_previous_status;
  end if;

  -- Recheck under both locks. An earlier Edge lookup cannot authorize this write.
  if v_checkout.status <> 'provider_pending' or v_checkout.expires_at <= clock_timestamp()
    or v_checkout.payment_provider is distinct from p_provider
    or nullif(trim(p_provider_event_id),'') is null
    or nullif(trim(v_checkout.provider_checkout_id),'') is null
    or p_payload->>'provider_checkout_id' is distinct from v_checkout.provider_checkout_id
    or p_payload->'amount_cents' is distinct from to_jsonb(v_total)
    or upper(p_payload->>'currency') is distinct from upper(v_currency) then
    raise exception 'Payment does not match a current provider checkout';
  end if;

  for v_item in
    select oi.product_id,oi.product_variant_id,oi.quantity
    from public.order_items oi
    where oi.order_id=p_order_id
  loop
    if v_item.product_variant_id is not null then
      select * into v_variant
      from public.product_variants
      where id=v_item.product_variant_id
      for update;

      if v_variant.track_inventory and v_variant.inventory_quantity is not null then
        if v_variant.inventory_quantity < v_item.quantity then
          raise exception 'Insufficient variant inventory at payment confirmation';
        end if;

        update public.product_variants
        set inventory_quantity=inventory_quantity-v_item.quantity,
            updated_at=now()
        where id=v_item.product_variant_id;
      end if;
    else
      select * into v_product
      from public.products
      where id=v_item.product_id
      for update;

      if v_product.track_inventory and v_product.inventory_quantity is not null then
        if v_product.inventory_quantity < v_item.quantity then
          raise exception 'Insufficient product inventory at payment confirmation';
        end if;

        update public.products
        set inventory_quantity=inventory_quantity-v_item.quantity,
            updated_at=now()
        where id=v_item.product_id;
      end if;
    end if;
  end loop;

  update public.orders
  set status='paid',
      payment_provider=p_provider,
      provider_customer_id=p_provider_customer_id,
      provider_payment_id=p_provider_payment_id,
      shipping_name=coalesce(nullif(trim(p_shipping_name),''),shipping_name),
      shipping_address=coalesce(p_shipping_address,shipping_address),
      paid_at=now(),
      updated_at=now()
  where id=p_order_id;

  select id into v_session_id
  from public.checkout_sessions
  where order_id=p_order_id
  limit 1;

  if v_session_id is not null then
    update public.checkout_sessions
    set status='completed',completed_at=now(),updated_at=now()
    where id=v_session_id;

    update public.inventory_reservations
    set released_at=coalesce(released_at,now())
    where checkout_session_id=v_session_id;
  end if;

  if v_promo_id is not null then
    update public.promo_codes
    set redemption_count=redemption_count+1,updated_at=now()
    where id=v_promo_id;
  end if;

  if p_provider_event_id is not null then
    update public.payment_webhook_events
    set status='processed',processed_at=now()
    where provider=p_provider and provider_event_id=p_provider_event_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.publish_dc_entity(p_entity_type text, p_entity_id uuid, p_target_status text DEFAULT 'published'::text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not private.is_content_admin() then
    raise exception 'Content administrator access required';
  end if;

  if not private.has_approved_dc_review(p_entity_type,p_entity_id) then
    raise exception 'A current approved DC governance review is required before publishing.';
  end if;

  case p_entity_type
    when 'book' then
      if p_target_status not in ('coming_soon','published') then raise exception 'Invalid book publish status'; end if;
      update public.books set status=p_target_status where id=p_entity_id;
    when 'adventure' then
      if p_target_status not in ('scheduled','published') then raise exception 'Invalid adventure publish status'; end if;
      update public.adventures set status=p_target_status where id=p_entity_id;
    when 'challenge' then
      if p_target_status not in ('scheduled','published') then raise exception 'Invalid challenge publish status'; end if;
      update public.challenges set status=p_target_status where id=p_entity_id;
    when 'content_item' then
      if p_target_status not in ('scheduled','published') then raise exception 'Invalid content publish status'; end if;
      update public.content_items set status=p_target_status where id=p_entity_id;
    when 'scripture_passage' then
      if p_target_status <> 'published' then raise exception 'Invalid Scripture publish status'; end if;
      update public.scripture_passages set status='published' where id=p_entity_id;
    when 'power_verse' then
      if p_target_status <> 'published' then raise exception 'Invalid Power Verse publish status'; end if;
      update public.power_verses set status='published' where id=p_entity_id;
    when 'devotional_series' then
      if p_target_status not in ('scheduled','published') then raise exception 'Invalid devotional publish status'; end if;
      update public.devotional_series set status=p_target_status where id=p_entity_id;
    when 'prayer_prompt' then
      if p_target_status <> 'published' then raise exception 'Invalid prayer publish status'; end if;
      update public.prayer_prompts set status='published' where id=p_entity_id;
    when 'identity_truth' then
      if p_target_status <> 'published' then raise exception 'Invalid identity truth publish status'; end if;
      update public.identity_truths set status='published' where id=p_entity_id;
    when 'family_faith_guide' then
      if p_target_status not in ('scheduled','published') then raise exception 'Invalid Family Faith publish status'; end if;
      update public.family_faith_guides set status=p_target_status where id=p_entity_id;
    when 'event' then
      if p_target_status <> 'published' then raise exception 'Invalid event publish status'; end if;
      update public.events set status='published' where id=p_entity_id;
    when 'product' then
      if p_target_status <> 'active' then raise exception 'Invalid product publish status'; end if;
      update public.products set status='active' where id=p_entity_id;
    else
      raise exception 'Unsupported DC governance entity type';
  end case;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_household_consent(p_household_id uuid, p_consent_key text, p_action text, p_child_profile_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_policy_version text;
  v_id uuid;
begin
  if not private.can_manage_household(p_household_id) then
    raise exception 'Guardian household access required';
  end if;

  if p_action not in ('granted','revoked') then
    raise exception 'Consent action must be granted or revoked';
  end if;

  select current_policy_version
    into v_policy_version
  from public.consent_policies
  where consent_key=p_consent_key
    and is_active=true;

  if v_policy_version is null then
    raise exception 'Consent policy not found';
  end if;

  if p_child_profile_id is not null and not exists (
    select 1 from public.child_profiles cp
    where cp.id=p_child_profile_id
      and cp.household_id=p_household_id
  ) then
    raise exception 'Child does not belong to this household';
  end if;

  insert into public.household_consents(
    household_id,
    guardian_user_id,
    child_profile_id,
    consent_key,
    action,
    policy_version,
    metadata
  )
  values(
    p_household_id,
    (select auth.uid()),
    p_child_profile_id,
    p_consent_key,
    p_action,
    v_policy_version,
    coalesce(p_metadata,'{}'::jsonb)
  )
  returning id into v_id;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_household_adult(p_household_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_role text;
begin
  if not private.is_household_owner(p_household_id) then
    raise exception 'Household owner access required';
  end if;

  select role into v_role
  from public.household_members
  where household_id=p_household_id
    and user_id=p_user_id
    and status='active';

  if v_role is null then
    raise exception 'Household member not found';
  end if;

  if v_role='owner' then
    raise exception 'Household owner cannot be removed';
  end if;

  update public.household_members
  set status='removed'
  where household_id=p_household_id
    and user_id=p_user_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_data_privacy_action(p_household_id uuid, p_request_type text, p_child_profile_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
begin
  if not private.can_manage_household(p_household_id) then
    raise exception 'Guardian household access required';
  end if;

  if p_request_type not in ('export_household','export_child','delete_child','delete_household') then
    raise exception 'Unsupported privacy request';
  end if;

  if p_request_type in ('export_child','delete_child') and p_child_profile_id is null then
    raise exception 'A child profile is required for this request';
  end if;

  if p_child_profile_id is not null and not exists (
    select 1 from public.child_profiles cp
    where cp.id=p_child_profile_id
      and cp.household_id=p_household_id
  ) then
    raise exception 'Child does not belong to this household';
  end if;

  insert into public.data_privacy_requests(
    household_id,
    child_profile_id,
    requested_by,
    request_type,
    reason,
    status
  )
  values(
    p_household_id,
    p_child_profile_id,
    (select auth.uid()),
    p_request_type,
    nullif(trim(p_reason),''),
    'requested'
  )
  returning id into v_id;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_dc_content_review(p_entity_type text, p_entity_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_errors text;
begin
  if not private.is_content_admin() then
    raise exception 'Content administrator access required';
  end if;

  select string_agg(message,' ')
    into v_errors
  from public.dc_preflight_scan(p_entity_type,p_entity_id)
  where severity='error';

  if v_errors is not null then
    raise exception 'DC preflight must pass before review: %',v_errors;
  end if;

  update public.dc_content_reviews
  set status='superseded',updated_at=now()
  where entity_type=p_entity_type
    and entity_id=p_entity_id
    and status in ('pending','changes_requested','approved');

  insert into public.dc_content_reviews(
    entity_type,entity_id,requested_by,notes,standard_versions
  )
  values(
    p_entity_type,
    p_entity_id,
    (select auth.uid()),
    nullif(trim(p_notes),''),
    jsonb_build_object(
      'creative_bible','2026.1',
      'production_manual','2026.1',
      'word_of_faith_guardrail','2026.1',
      'child_safety','2026.1',
      'brand_assets','2026.1'
    )
  )
  returning id into v_id;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.restore_child_profile(p_child_profile_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not private.can_manage_child(p_child_profile_id) then
    raise exception 'Guardian access required';
  end if;

  update public.child_profiles
  set status='active'
  where id=p_child_profile_id
    and status='archived';

  if not found then
    raise exception 'Archived child profile not found';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.return_parent_challenge(p_progress_id uuid, p_guardian_session_token text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_child_id uuid;
  v_household_id uuid;
  v_submitted_at timestamptz;
begin
  select ccp.child_profile_id, cp.household_id, ccp.submitted_at
  into v_child_id, v_household_id, v_submitted_at
  from public.child_challenge_progress ccp
  join public.child_profiles cp on cp.id = ccp.child_profile_id
  where ccp.id = p_progress_id and ccp.status = 'pending_parent';

  if v_child_id is null then
    raise exception 'Pending challenge approval not found';
  end if;
  if not private.guardian_unlock_session_valid(v_household_id, p_guardian_session_token) then
    raise exception 'Guardian unlock session is invalid or expired';
  end if;

  update public.child_challenge_progress
  set status = 'in_progress', submitted_at = null
  where id = p_progress_id
    and child_profile_id = v_child_id
    and status = 'pending_parent'
    and submitted_at is not distinct from v_submitted_at;
  if not found then
    raise exception 'Challenge changed while being reviewed. Refresh the approval queue.';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.revoke_household_invitation(p_invitation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_household_id uuid;
begin
  select household_id into v_household_id
  from public.household_invitations
  where id=p_invitation_id;

  if v_household_id is null
     or not private.can_manage_household(v_household_id) then
    raise exception 'Guardian access required';
  end if;

  update public.household_invitations
  set status='revoked'
  where id=p_invitation_id
    and status='pending';
end;
$function$

CREATE OR REPLACE FUNCTION public.save_family_challenge_participants(p_household_id uuid, p_challenge_id uuid, p_child_ids uuid[], p_action text, p_step_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS TABLE(child_profile_id uuid, status text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_child uuid; v_ids uuid[]; v_progress uuid; v_status text; v_approval boolean;
begin
 if (select auth.uid()) is null or not private.can_manage_household(p_household_id) then
  raise exception 'Guardian household access required'; end if;
 if p_action is null or p_action not in ('participate','complete') then raise exception 'Invalid family action'; end if;
 select array_agg(distinct x order by x) into v_ids from unnest(p_child_ids) x;
 if coalesce(cardinality(v_ids),0)=0 or cardinality(v_ids)>100 or array_position(v_ids,null) is not null then
  raise exception 'Choose participating children'; end if;
 -- Validate the entire selection before any writes. Any later failure also rolls back all children.
 if exists(select 1 from unnest(v_ids) x where not exists(select 1 from public.child_profiles cp
   where cp.id=x and cp.household_id=p_household_id and cp.status='active')
   or not private.child_can_access_challenge(x,p_challenge_id)) then
  raise exception 'Every participant must have access to this challenge in this household'; end if;
 select c.parent_approval_required into v_approval from public.challenges c where c.id=p_challenge_id;
 if not found then raise exception 'Challenge access required'; end if;
 if exists(select 1 from unnest(p_step_ids) x where x is null or not exists(
   select 1 from public.challenge_steps cs where cs.id=x and cs.challenge_id=p_challenge_id)) then
  raise exception 'Invalid challenge step'; end if;
 if p_action='complete' and exists(select 1 from public.challenge_steps cs
   where cs.challenge_id=p_challenge_id and cs.is_required and not(cs.id=any(coalesce(p_step_ids,'{}')))) then
  raise exception 'Confirm every required step for the selected children'; end if;
 foreach v_child in array v_ids loop
  insert into public.child_challenge_progress(child_profile_id,challenge_id,status,started_at)
   values(v_child,p_challenge_id,'in_progress',now())
   on conflict on constraint child_challenge_progress_child_profile_id_challenge_id_key do nothing;
  select p.id,p.status into v_progress,v_status from public.child_challenge_progress p
   where p.child_profile_id=v_child and p.challenge_id=p_challenge_id for update;
  if v_progress is null then raise exception 'Progress could not be confirmed'; end if;
  if v_status not in ('completed','pending_parent') then
   insert into public.child_step_progress(child_challenge_progress_id,challenge_step_id,completed,completed_at)
    select v_progress,x,true,now() from (select distinct unnest(p_step_ids) x) s
    on conflict (child_challenge_progress_id,challenge_step_id) do update set completed=true,completed_at=excluded.completed_at;
   update public.child_challenge_progress p set
    status=case when p_action='complete' then case when v_approval then 'pending_parent' else 'completed' end else 'in_progress' end,
    started_at=coalesce(p.started_at,now()),submitted_at=case when p_action='complete' then now() else p.submitted_at end
    where p.id=v_progress returning p.status into v_status;
  end if;
  child_profile_id:=v_child; status:=v_status; return next;
 end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.withdraw_child_from_group(p_group_id uuid, p_child_profile_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if (select auth.uid()) is null or not private.can_manage_child(p_child_profile_id) then
    raise exception 'Guardian access required';
  end if;
  perform 1 from public.child_profiles where id=p_child_profile_id for update;
  update public.child_group_memberships
  set status='withdrawn',ended_at=coalesce(ended_at,now())
  where group_id=p_group_id and child_profile_id=p_child_profile_id;
  if not found then raise exception 'Group membership not found'; end if;
end;
$function$
